package com.kolipri.uzzap.data

import android.os.Handler
import android.os.Looper
import com.kolipri.uzzap.BuildConfig
import com.kolipri.uzzap.model.ModerationAction
import com.kolipri.uzzap.model.UserReport
import okhttp3.*
import org.json.JSONArray
import org.json.JSONObject
import java.io.IOException
import java.util.concurrent.TimeUnit

/** Safety/moderation client backed by the current UUID-based Supabase schema. */
object SafetyClient {
    private val main=Handler(Looper.getMainLooper())
    private val http=OkHttpClient.Builder().connectTimeout(8,TimeUnit.SECONDS).readTimeout(12,TimeUnit.SECONDS).writeTimeout(12,TimeUnit.SECONDS).build()
    private val url=BuildConfig.SUPABASE_URL.trimEnd('/');private val key=BuildConfig.SUPABASE_ANON_KEY;private val json="application/json; charset=utf-8".toMediaType()
    private fun req(path:String)=Request.Builder().url("$url$path").header("apikey",key).header("Authorization","Bearer ${SupabaseClient.userAccessToken.orEmpty()}").header("Content-Type","application/json")
    private fun rpc(name:String,body:JSONObject,cb:Callback)=http.newCall(req("/rest/v1/rpc/$name").post(body.toString().toRequestBody(json)).build()).enqueue(cb)
    private fun currentId():String?{val token=SupabaseClient.userAccessToken?:return null;return runCatching{val p=token.split('.').getOrNull(1)?:return@runCatching null;val bytes=android.util.Base64.decode(p,android.util.Base64.URL_SAFE or android.util.Base64.NO_WRAP or android.util.Base64.NO_PADDING);JSONObject(String(bytes,Charsets.UTF_8)).optString("sub").ifBlank{null}}.getOrNull()}
    private fun uuidForUsername(username:String,cb:(String?)->Unit){rpc("get_user_id_by_username",JSONObject().put("p_username",username),object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{cb(null)};override fun onResponse(c:Call,r:Response){r.use{if(!it.isSuccessful){main.post{cb(null)};return};main.post{cb(it.body?.string()?.trim()?.removeSurrounding("\"")?.ifBlank{null})}}}})}
    private fun uuidForRoom(room:String,cb:(String?)->Unit){rpc("get_room_id_by_name",JSONObject().put("p_room_name",room),object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{cb(null)};override fun onResponse(c:Call,r:Response){r.use{if(!it.isSuccessful){main.post{cb(null)};return};main.post{cb(it.body?.string()?.trim()?.removeSurrounding("\"")?.ifBlank{null})}}}})}

    fun isBlocked(username:String,onResult:(Boolean)->Unit){uuidForUsername(username){uid->val me=currentId();if(uid==null||me==null){main.post{onResult(false)};return@uuidForUsername};val path="/rest/v1/blocks?blocker_id=eq.$me&blocked_id=eq.$uid&select=blocked_id&limit=1";http.newCall(req(path).get().build()).enqueue(object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{onResult(false)};override fun onResponse(c:Call,r:Response){r.use{main.post{onResult(it.isSuccessful&&JSONArray(it.body?.string().orEmpty()).length()>0)}}}})}}
    fun block(username:String,onResult:(Boolean)->Unit){uuidForUsername(username){uid->if(uid==null){main.post{onResult(false)};return@uuidForUsername};rpc("set_blocked_user",JSONObject().put("p_other_user",uid).put("p_blocked",true),simple(onResult))}}
    fun unblock(username:String,onResult:(Boolean)->Unit){uuidForUsername(username){uid->if(uid==null){main.post{onResult(false)};return@uuidForUsername};rpc("set_blocked_user",JSONObject().put("p_other_user",uid).put("p_blocked",false),simple(onResult))}}
    fun report(username:String,reason:String,details:String,onResult:(Boolean)->Unit){uuidForUsername(username){uid->if(uid==null){main.post{onResult(false)};return@uuidForUsername};rpc("submit_user_report",JSONObject().put("p_reported_user",uid).put("p_reason",reason.take(100)).put("p_details",details.take(2000)),simple(onResult))}}

    fun fetchReports(status:String?=null,onResult:(List<UserReport>)->Unit){rpc("get_reports_for_moderators",JSONObject().apply{if(!status.isNullOrBlank())put("p_status",status)},object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{onResult(emptyList())};override fun onResponse(c:Call,r:Response){r.use{if(!it.isSuccessful){main.post{onResult(emptyList())};return};val list=mutableListOf<UserReport>();runCatching{val a=JSONArray(it.body?.string().orEmpty());for(i in 0 until a.length()){val o=a.getJSONObject(i);list.add(UserReport(MessageIdRegistry.register(o.optString("id")),o.optString("reporter_id").ifBlank{null},o.optString("reported_username"),o.optString("reason"),o.optString("details").ifBlank{null},o.optString("status"),o.optString("created_at")))}};main.post{onResult(list)}}}})}
    fun updateReportStatus(reportId:Long,status:String,onResult:(Boolean)->Unit){val uuid=MessageIdRegistry.uuidFor(reportId);if(uuid==null){main.post{onResult(false)};return};val valid=when(status.lowercase()){"pending","open"->"open";"reviewing"->"reviewing";"resolved"->"resolved";"dismissed"->"dismissed";else->null};if(valid==null){main.post{onResult(false)};return};rpc("update_report_status",JSONObject().put("p_report_id",uuid).put("p_status",valid),simple(onResult))}

    fun applyModerationAction(targetUsername:String,actionType:String,roomName:String?,reason:String,durationMinutes:Int?,onResult:(Boolean)->Unit){uuidForUsername(targetUsername){uid->if(uid==null){main.post{onResult(false)};return@uuidForUsername};if(roomName.isNullOrBlank()){rpc("moderate_user_action",JSONObject().put("p_target_user",uid).put("p_action",actionType).put("p_reason",reason.take(500)).apply{if(durationMinutes!=null)put("p_duration_minutes",durationMinutes)},simple(onResult));return@uuidForUsername};uuidForRoom(roomName){rid->if(rid==null){main.post{onResult(false)};return@uuidForRoom};rpc("moderate_user_action",JSONObject().put("p_target_user",uid).put("p_action",actionType).put("p_room_id",rid).put("p_reason",reason.take(500)).apply{if(durationMinutes!=null)put("p_duration_minutes",durationMinutes)},simple(onResult))}}}
    fun fetchActiveModerationActions(onResult:(List<ModerationAction>)->Unit){val path="/rest/v1/moderation_actions?order=created_at.desc&select=*";http.newCall(req(path).get().build()).enqueue(object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{onResult(emptyList())};override fun onResponse(c:Call,r:Response){r.use{if(!it.isSuccessful){main.post{onResult(emptyList())};return};val list=mutableListOf<ModerationAction>();runCatching{val a=JSONArray(it.body?.string().orEmpty());for(i in 0 until a.length()){val o=a.getJSONObject(i);list.add(ModerationAction(MessageIdRegistry.register(o.optString("id")),o.optString("moderator_id").ifBlank{null},o.optString("target_user_id"),o.optString("action"),o.optString("room_id").ifBlank{null},o.optString("reason"),o.optString("expires_at").ifBlank{null},o.optString("created_at")))}};main.post{onResult(list)}}}})}
    fun revokeModerationAction(actionId:Long,onResult:(Boolean)->Unit){val uuid=MessageIdRegistry.uuidFor(actionId);if(uuid==null){main.post{onResult(false)};return};rpc("revoke_moderation_action",JSONObject().put("p_action_id",uuid),simple(onResult))}
    fun deleteRoomMessage(messageId:Long,onResult:(Boolean)->Unit){val uuid=MessageIdRegistry.uuidFor(messageId);if(uuid==null){main.post{onResult(false)};return};rpc("moderate_message_delete",JSONObject().put("p_message_id",uuid).put("p_reason","Moderator deletion"),simple(onResult))}
    fun checkUserMuted(username:String,roomName:String?,onResult:(Boolean,String?)->Unit){uuidForUsername(username){uid->if(uid==null){main.post{onResult(false,null)};return@uuidForUsername};uuidForRoom(roomName?:""){rid->if(rid==null){main.post{onResult(false,null)};return@uuidForRoom};val path="/rest/v1/room_mutes?user_id=eq.$uid&room_id=eq.$rid&select=expires_at&limit=1";http.newCall(req(path).get().build()).enqueue(object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{onResult(false,null)};override fun onResponse(c:Call,r:Response){r.use{if(!it.isSuccessful){main.post{onResult(false,null)};return};val a=JSONArray(it.body?.string().orEmpty());val active=a.length()>0;main.post{onResult(active,if(active)"Muted by a moderator" else null)}}}})}}}
    private fun simple(onResult:(Boolean)->Unit)=object:Callback{override fun onFailure(c:Call,e:IOException)=main.post{onResult(false)};override fun onResponse(c:Call,r:Response){r.use{main.post{onResult(it.isSuccessful)}}}}
}
